import json, re, sys
from datetime import datetime

rows = [json.loads(l) for l in open('commits.jsonl', encoding='utf-8') if l.strip()]

# ---- mailmap
canon = {}
for line in open('.mailmap', encoding='utf-8'):
    s = line.strip()
    if not s or s.startswith('#'):
        continue
    m = re.match(r'^(.*?)\s*<([^>]*)>\s*<([^>]*)>$', s)
    if m:
        canon[m.group(3).strip().lower()] = m.group(1).strip()

def cname(name, email):
    return canon.get((email or '').strip().lower(), name)

# ---- reverts
revert_prefixes = []
for r in rows:
    head = r['message'].splitlines()[0]
    if head.startswith('Revert "'):
        for ln in r['message'].splitlines()[1:]:
            m = re.match(r'^This reverts commit ([0-9a-fA-F]{7,40})\.$', ln.strip())
            if m:
                revert_prefixes.append(m.group(1).lower())

def is_reverted(h):
    return any(h.lower().startswith(p) for p in revert_prefixes)

H = re.compile(r'^([a-z]+)(?:\(([^\s()]+)\))?(!)?: (.+)$')

TITLES = {'breaking': 'Breaking changes', 'feat': 'Features', 'fix': 'Fixes'}
entries = []   # dicts: section, scope, summary, time, hash, refs
note_commits = []

for r in rows:
    head = r['message'].splitlines()[0]
    if head.startswith('Revert "') or is_reverted(r['hash']):
        continue
    m = H.match(head)
    if not m:
        continue
    typ, scope, bang, summary = m.group(1), m.group(2), m.group(3), m.group(4)
    scope = scope if scope else 'general'
    breaking = bool(bang)
    if breaking:
        section = 'breaking'
    elif typ in ('feat', 'fix', 'perf'):
        section = 'feat' if typ in ('feat', 'perf') else 'fix'
    else:
        continue
    if scope == 'internal' and not breaking:
        continue
    s = summary[0].upper() + summary[1:]
    if s.endswith('.'):
        s = s[:-1]
    if typ == 'perf':
        s += ' [perf]'
    disp_scope = 'dependencies' if scope == 'deps' else scope
    refs = []
    if typ == 'fix':
        for ln in r['message'].splitlines()[1:]:
            mm = re.fullmatch(r'Fixes #([0-9]+)', ln)
            if mm:
                refs.append(int(mm.group(1)))
    entries.append({'section': section, 'scope': disp_scope, 'summary': s,
                    'time': datetime.fromisoformat(r['date']), 'hash': r['hash'],
                    'refs': refs})
    note_commits.append(r)

# ---- merge
groups = {}
for e in entries:
    groups.setdefault((e['section'], e['scope'], e['summary']), []).append(e)

def render(scope, summary, refs, hashes):
    line = '- **%s:** %s' % (scope, summary)
    if refs:
        line += ' (%s)' % ', '.join('#%d' % n for n in refs)
    line += ' (%s)' % ', '.join(hashes)
    return line

rendered = []
for (section, scope, summary), es in groups.items():
    es.sort(key=lambda e: e['time'], reverse=True)
    seen = []
    for e in es:
        for n in e['refs']:
            if n not in seen:
                seen.append(n)
    hashes = [e['hash'][:7] for e in es]
    line = render(scope, summary, seen, hashes)
    if len(line) > 100:
        suffix = ''
        if seen:
            suffix += ' (%s)' % ', '.join('#%d' % n for n in seen)
        suffix += ' (%s)' % ', '.join(hashes)
        avail = 100 - len('- **%s:** ' % scope) - len(suffix) - 1
        trunc = summary[:max(avail, 0)].rstrip(' ')
        line = render(scope, trunc + '\u2026', seen, hashes)
    rendered.append({'section': section, 'scope': scope,
                     'time': max(e['time'] for e in es), 'line': line})

order = ['breaking', 'feat', 'fix']
blocks = []
for sec in order:
    items = [x for x in rendered if x['section'] == sec]
    if not items:
        continue
    items.sort(key=lambda x: x['scope'])
    items.sort(key=lambda x: (x['scope'], [-x['time'].timestamp()][0]))
    # stable: sort by time desc within scope
    items.sort(key=lambda x: x['time'], reverse=True)
    items.sort(key=lambda x: x['scope'])
    blocks.append('## %s\n\n%s\n' % (TITLES[sec], '\n'.join(x['line'] for x in items)))

# ---- contributors
counts = {}
authored = set()
bots = set()
credit = {}
for r in note_commits:
    names = set()
    a = cname(r['author'], r['email'])
    if a.endswith('[bot]'):
        bots.add(a)
    else:
        authored.add(a)
        names.add(a)
    for ln in r['message'].splitlines():
        m = re.match(r'^Co-authored-by:\s*(.*?)\s*<([^>]*)>\s*$', ln)
        if m:
            n = cname(m.group(1).strip(), m.group(2))
            if not n.endswith('[bot]'):
                names.add(n)
    credit[r['hash']] = names
for h, names in credit.items():
    for n in names:
        if n in authored:
            counts[n] = counts.get(n, 0) + 1

people = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
lines = ['# Release 4.2.0', '']
for b in blocks:
    lines.append(b)
lines.append('## Contributors\n\n%s' % '\n'.join('- %s (%d)' % (n, c) for n, c in people))
out = '\n'.join(lines) + '\n'
sys.stdout.write(out)
print('NOTE_COMMITS', len(note_commits), file=sys.stderr)
print('ENTRIES_AFTER_MERGE', len(rendered), file=sys.stderr)
print('MAXLEN', max(len(l) for l in out.split('\n')), file=sys.stderr)
EOF
